DELIMITER $$
--
-- Prosedur
--
CREATE DEFINER=`scsbanja`@`localhost` PROCEDURE `GenerateDummyOrders` ()   BEGIN
    -- Variabel untuk menyimpan data saat looping
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_id_dapur INT;
    DECLARE v_nama_dapur VARCHAR(100);
    DECLARE v_id_pesanan_baru INT;
    
    -- Cursor untuk mengambil HANYA user dengan role 'dapur' (ID 2, 5, 6, dst otomatis)
    DECLARE cur_dapur CURSOR FOR 
        SELECT id, nama FROM user WHERE role = 'dapur';
    
    -- Handler agar loop berhenti saat data habis
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur_dapur;

    read_loop: LOOP
        FETCH cur_dapur INTO v_id_dapur, v_nama_dapur;
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- ==========================================
        -- LANGKAH 1: Buat Header Pesanan (Kosongan)
        -- ==========================================
            id_dapur, nama_pemesan, wa_pemesan, nama_driver, 
            status_pembayaran, status_pengiriman, tgl_pesan, total_harga
        ) VALUES (
            v_id_dapur, 
            CONCAT('Orderan ', v_nama_dapur), -- Nama Pemesan Custom
            '081234567890', 
            '-', -- Driver strip dulu karena masih pending
            'Belum Bayar', 
            'Pending', 
            NOW(), 
            0 -- Total dihitung nanti
        );

        -- Ambil ID Pesanan yang baru saja dibuat
        SET v_id_pesanan_baru = LAST_INSERT_ID();

        -- ==========================================
        -- LANGKAH 2: Masukkan Detail Barang & Potong Stok
        -- Kita pakai barang yang STOK-nya BANYAK biar aman
        -- ==========================================

        -- ITEM 1: Beras (ID 47) - Beli 10 Kg
        SELECT v_id_pesanan_baru, 47, 10, harga, harga, IFNULL(harga_beli, 0)
        FROM gudang WHERE id_barang = 47;

        UPDATE gudang SET stok = stok - 10 WHERE id_barang = 47;

        -- ITEM 2: Minyak Goreng (ID 41) - Beli 5 Pcs
        SELECT v_id_pesanan_baru, 41, 5, harga, harga, IFNULL(harga_beli, 0)
        FROM gudang WHERE id_barang = 41;

        UPDATE gudang SET stok = stok - 5 WHERE id_barang = 41;

        -- ITEM 3: A_EXAMPLE_2 (ID 282) - Beli 20 Sachet
        SELECT v_id_pesanan_baru, 282, 20, harga, harga, IFNULL(harga_beli, 0)
        FROM gudang WHERE id_barang = 282;

        UPDATE gudang SET stok = stok - 20 WHERE id_barang = 282;

        -- ==========================================
        -- LANGKAH 3: Hitung Total Harga Otomatis
        -- ==========================================
        UPDATE pesanan 
        SET total_harga = (
            SELECT SUM(jumlah * harga_jual_saat_itu) 
            FROM detail_pesanan 
            WHERE id_pesanan = v_id_pesanan_baru
        )
        WHERE id_pesanan = v_id_pesanan_baru;

    END LOOP;

    CLOSE cur_dapur;
END$$

DELIMITER ;

